 function walkStep(index,select=true){if(!walkCurrent())return bridge.toast('The source architecture changed. Restart this review trail.');walk.step=Math.max(0,Math.min(4,index));walk.visited=[...new Set([...walk.visited,walk.step])];const ids=trail().steps[walk.step].ids;if(select&&ids[0])bridge.state.selected=ids[0];if(select)bridge.render();else refreshWalk()}
 function refreshWalk(){const panel=document.querySelector('#flow-panel');if(!walk||!panel?.querySelector('.rv-walk-result'))return bridge.render();const t=trail(),step=t.steps[walk.step];bridge.refreshGraph?.();panel.querySelector('[data-rv-action="walk-play"]').textContent=walk.playing?'Pause':'Play';panel.querySelector('[data-rv-action="trace-review"]').disabled=walk.visited.length!==5||!walkCurrent();panel.querySelectorAll('.rv-walk-stages button').forEach((button,i)=>{button.classList.toggle('active',i===walk.step);button.textContent=(walk.visited.includes(i)?'✓ ':'')+(i+1)+'. '+t.steps[i].title});panel.querySelector('.rv-walk-result').innerHTML=walkResult(t,step)}
 function play(){if(!walkCurrent())return;if(walk.playing){pause();refreshWalk();return}if(walk.step===4){walk.step=0;walk.visited=[0]}walk.playing=true;refreshWalk();const next=()=>{if(!walk?.playing||bridge.state.chapter!==11||bridge.state.tab!=='model')return pause();if(walk.step>=4){pause();refreshWalk();return}walkStep(walk.step+1,false);timer=setTimeout(next,1700)};timer=setTimeout(next,1700)}
 function recordTrace(){pause();if(!walkCurrent())return;dialog('Record '+walk.requirementId+' traceability review','<p>The walkthrough reviews declared architecture links. It does not verify the running system.</p><form id="rv-trace-form">'+recordField('review.trace','reviewer','')+recordField('review.trace','notes','')+recordField('review.trace','reviewed',false)+end('Record traceability review')+'</form>','trace')}
 function walkResult(t,step){return '<span class="eyebrow">Step '+(walk.step+1)+' of 5</span><h3>'+esc(step.title)+'</h3><p>'+esc(step.detail)+'</p>'+(walk.step===0?sourceLink(1,t.requirement.id,t.requirement.id+' · '+t.requirement.title):walk.step===1?t.drivers.map(d=>sourceLink(2,d.id,d.id+' · '+d.title)).join('')+t.decisions.map(d=>sourceLink(3,d.id,d.id+' · '+d.status)).join(''):'')}
 function failureSurface(){const t=trail();if(!t)return '<p>No in-scope requirement is available. Review Chapter 1 scope.</p>';if(!walk)return '<div class="t-failure-invite"><div><span class="eyebrow">'+esc(t.requirement.id)+' / Architecture review trail</span><p>Follow the obligation through quality, choices, responsibilities, supporting services, and runtime. This is a design walkthrough.</p></div>'+B('walk','Follow the trail','gold')+'</div>';const step=t.steps[walk.step];return '<div class="rv-walk-head"><span class="eyebrow">'+esc(t.requirement.id)+' / Design traceability</span>'+badge(walkCurrent()?'Current model':'Source changed · restart required',!walkCurrent())+'</div><div class="rv-actions rv-transport">'+B('walk','Restart')+B('walk-next','Step')+B('walk-play',walk.playing?'Pause':'Play')+B('trace-review','Record trace review','gold',walk.visited.length===5&&walkCurrent()?{}:{disabled:'disabled'})+B('close-walk','Close trail','text-button')+'</div><nav class="rv-walk-stages" aria-label="Traceability review stages">'+t.steps.map((s,i)=>B('walk-step',(walk.visited.includes(i)?'✓ ':'')+(i+1)+'. '+s.title,walk.step===i?'active':'',{'data-rv-step':i})).join('')+'</nav><div class="rv-walk-result">'+walkResult(t,step)+'</div>'}
