function validation(){return validationSurfaceHTML(project(),11,{title:'Challenge the design. Keep the evidence.',purpose:'Resolve final review checks and assess inherited findings while preserving their sources and treatments.',run:B('checks','Run current checks','primary'),actions:B('record',finalChecksCurrent(project())?'Record architect review':'Record architect review · run checks first')+B('baseline',latestDesignReview(project())?'Prepare baseline':'Prepare baseline · record review first'),findings:[...finalFindings(project()).map(f=>({...f,set:'final',objectId:f.objectId||'project',title:checkWords(f.title),detail:checkWords(f.detail),actions:f.code==='source-findings'?'<button type="button" class="btn" data-validation-set="source">Assess inherited findings</button>':B('fix','Open remedy','',{'data-rv-id':f.id})})),...inheritedFindings(project()).map(f=>({...f,set:'source',sourceChapter:f.chapter,sourceFinding:f,treated:findingWord(f)==='treated',treatmentText:findingTreatment(project(),f),reference:recordRef(project(),f.objectId)||f.objectId,actions:B('disposition','Treat this finding','',{'data-rv-id':f.id})+sourceLink(f.chapter,f.objectId,'Open source','validate')}))]});}
 function fix(id){const f=finalFindings(project()).find(f=>f.id===id);if(!f)return;close(true);if(f.code==='change-review')return openChangeReview();if(f.code==='intake')return intake();if(f.code==='narrative')return narrative();if(f.code==='architecture-obligation')return editObligation(f.objectId);if(f.code==='verification-comparison')return delivery(f.objectId);if(f.code==='trace'){chooseRequirement(f.objectId);return startWalk()}if(['action-definition','action-source','verification','delivery-blocked'].includes(f.code))return editAction(f.objectId);if(['design-review','revision'].includes(f.code))return recordReview();if(f.code==='baseline')return freeze();if(f.code.startsWith('governance'))return governance();if(f.code.startsWith('ROADMAP')){stage='plateaus';bridge.setTab('work');return}bridge.render();document.querySelector('.rv-filter-row')?.scrollIntoView({block:'start'})}
 function downloadLink(label,format,b=null){return '<a class="btn" href="/api/export?chapter=11&amp;format='+format+(b?'&amp;baseline='+encodeURIComponent(b.id):'')+'" download="'+projectFileName('AIW_Bank_Payment_'+(b?b.id:format==='json'?'Project_Export':'Working_SDD')+'.'+format)+'">'+esc(label)+'</a>'}
