 function boardHTML(){let R=null;const lens=shellLens();try{R=lens?scopedBoard(project(),lens):sddBoard(project())}catch(e){console.warn('The SDD readiness board could not be read.',e?.message);return ''}const n=v=>(Number(v)||0).toLocaleString('en-GB'),unit=(v,u)=>counted(v,u).replace(/^[\d,]+ /,'');
  const tile=c=>'<li class="rv-tile '+esc(c.state)+'"><div class="rv-tile-h"><span>'+String(c.chapter).padStart(2,'0')+'</span><b>'+esc(c.title)+'</b></div><p class="rv-tile-c"><span class="pass"><b>'+n(c.passing)+'</b> of '+esc(counted(c.total,'passage'))+' passing</span><span class="fix"><b>'+n(c.toFix)+'</b> '+esc(unit(c.toFix,checkUnits(c.chapter).fix))+'</span><span class="confirm"><b>'+n(c.toConfirm)+'</b> '+esc(unit(c.toConfirm,checkUnits(c.chapter).confirm))+'</span>'+(c.treated?'<span class="treated"><b>'+n(c.treated)+'</b> '+(c.treated===1?'finding':'findings')+' treated</span>':'')+'</p><p class="rv-tile-next"><small>Next</small><a href="'+esc(c.next.url)+'">'+esc(c.next.text)+'</a></p><a class="rv-tile-go" href="'+esc(c.validateURL)+'">Chapter '+c.chapter+' checks <span aria-hidden="true">→</span></a></li>';
  return '<section class="rv-board" aria-labelledby="rv-board-title"><header><div><small>SDD readiness</small><h3 id="rv-board-title">Each chapter, as the SDD will read it</h3></div><p class="rv-board-sum"><span class="pass"><b>'+R.clear+'</b> of 11 chapters passing</span><span class="fix"><b>'+n(R.toFix)+'</b> '+esc(unit(R.toFix,'fix'))+'</span><span class="confirm"><b>'+n(R.toConfirm)+'</b> '+esc(unit(R.toConfirm,'confirm'))+'</span></p></header>'+(R.scope?'<p class="rv-board-note rv-board-scope" role="status">Read for '+esc(R.scope)+': Chapters 1 to 10 count the passages of the records this module shows; Chapter 11 and the SDD read the whole design. <button type="button" class="text-button" data-action="clear-scope">Read the whole design</button></p>':'')+'<p class="rv-board-note">Passing counts the passages of a chapter&rsquo;s part of the SDD with nothing open; to fix and to confirm count its open content gaps and review items. Read from the chapters&rsquo; rule-based checks and Chapter 11&rsquo;s treatments; it approves nothing.</p><ol class="rv-tiles">'+R.chapters.map(tile).join('')+'</ol></section>'}
